const $=id=>document.getElementById(id);
const CATEGORY={museum:'Science museum',nature_center:'Nature center',botanical_garden:'Botanical garden',observatory:'Planetarium / observatory',university:'University',research_center:'Research institute',zoo_aquarium:'Zoo / wildlife'};
const ICON={museum:'⚗',nature_center:'🌿',botanical_garden:'🌱',observatory:'✦',university:'▦',research_center:'⌬',zoo_aquarium:'🦉'};
const ACCESS_COLOR={public_venue:'#084B9E',scheduled_public:'#B68C3B',research_campus:'#9E382E'};
const PLACES=DATA.places.filter(p=>p.state==='TX').map(p=>({...p,lat:p.coordinates.lat,lng:p.coordinates.lng,dfw:p.region==='dfw'}));
let region='dfw',area='all',kind='all',access='all',selectedId=null;
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function collegeLabel(college){
 const level=college.level==='four_year'?'Four-year':'Two-year';
 return [college.community?'Community college':null,level,college.research].filter(Boolean).join(' · ');
}
const placeLabel=p=>p.college?collegeLabel(p.college):CATEGORY[p.category];
const eligible=()=>{
 const q=$('search').value.trim().toLowerCase();
 const type=$('collegeType').value,research=$('collegeResearch').value;
 function matchesKind(p){
  if(kind!=='university')return kind==='all'||p.category===kind;
  if(!p.college)return false;
  const matchesType=type==='all'||(type==='community'?p.college.community:p.college.level===type);
  return matchesType&&(research==='all'||p.college.research===research);
 }
 return PLACES.filter(p=>(region==='tx'||p.dfw)&&(region==='dfw'||area==='all'||p.region===area)&&matchesKind(p)&&(access==='all'||p.access.level===access)&&(!q||[p.name,p.city,p.summary,p.category,CATEGORY[p.category],placeLabel(p),p.access.label,...p.topics,...(p.college?.programs||[])].join(' ').toLowerCase().includes(q)));
};
const map=L.map('geoMap',{zoomControl:false,minZoom:3,maxZoom:19});
const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{
 maxZoom:19,updateWhenIdle:true,referrerPolicy:'strict-origin-when-cross-origin',
 attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
});
const failedTiles=new Set();
function updateTileStatus(){ $('streetStatus').classList.toggle('hidden',failedTiles.size===0) }
tiles.on('tileerror',e=>{failedTiles.add(e.tile);updateTileStatus()});
tiles.on('tileunload tileload',e=>{if(failedTiles.delete(e.tile))updateTileStatus()});
$('retryMap').onclick=()=>tiles.redraw();
tiles.addTo(map);
const clusters=L.markerClusterGroup({
 maxClusterRadius:36,showCoverageOnHover:false,
 iconCreateFunction:group=>{
  const count=group.getChildCount();
  return L.divIcon({className:'atlas-cluster',html:'<span aria-label="'+count+' nearby places">'+count+'</span>',iconSize:[34,34]});
 }
}).addTo(map);
const selection=L.layerGroup().addTo(map);
function renderPins(){
 clusters.clearLayers();selection.clearLayers();
 const markers=[];
 for(const p of eligible()){
  const selected=p.id===selectedId;
  const icon=L.divIcon({className:'atlas-pin'+(selected?' selected':''),
   html:'<span style="--pin-color:'+ACCESS_COLOR[p.access.level]+'"></span>',iconSize:[30,30]});
  const marker=L.marker([p.lat,p.lng],{icon,title:p.name,alt:p.name,zIndexOffset:selected?1000:0});
  if(selected){
   const card=document.createElement('article');
   card.className='venue-popup';
   const access=p.access.advisory==='temporarily_closed'?'Temporarily closed':p.access.label;
   card.innerHTML=`<strong>${esc(p.name)}</strong><small>${esc(placeLabel(p))} · ${esc(p.city)}</small><p>${esc(p.summary)}</p><small>${esc(access)}</small>`;
   marker.bindPopup(card,{
    maxWidth:Math.min(255,map.getSize().x-66),maxHeight:180,offset:[0,-10],
    autoPanPaddingTopLeft:[10,88],autoPanPaddingBottomRight:[12,26]
   });
   selection.addLayer(marker);
   marker.openPopup();
  }else{
   marker.on('click',()=>selectPlace(p.id,false));
   markers.push(marker);
  }
 }
 clusters.addLayers(markers);
}
function resetView(){
 const bounds=region==='tx'&&area==='all'?[[25.84,-106.65],[36.50,-93.50]]:
  PLACES.filter(p=>region==='dfw'?p.dfw:p.region===area).map(p=>[p.lat,p.lng]);
 map.fitBounds(bounds,{padding:[24,40],maxZoom:12,animate:false});
}
function renderList(){const list=eligible();$('resultCount').textContent=`${list.length} location${list.length!==1?'s':''} · ${region==='dfw'?'Dallas–Fort Worth focus':area==='all'?'statewide listings':$('area').selectedOptions[0].textContent}`;const root=$('placeList');root.replaceChildren();if(!list.length){root.innerHTML='<p class="no-results">No entries match those filters. Try another category or search.</p>';return}
 list.forEach(p=>{const b=document.createElement('button');b.type='button';b.className='place'+(p.id===selectedId?' selected':'');b.innerHTML=`<span class="marker-icon" aria-hidden="true">${ICON[p.category]}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.city)} · ${esc(placeLabel(p))}</small><em>${esc(p.access.label)}</em></span>`;b.addEventListener('click',()=>selectPlace(p.id,true));root.appendChild(b)});
}
function renderProfile(){const p=PLACES.find(p=>p.id===selectedId);const pane=$('profile');if(!p){const count=eligible().length;pane.innerHTML=`<div class="sec-label">Explore the directory</div><h2>Science happens nearby.</h2><div class="hero-stat">${count}</div><p class="hero-caption">places in your current selection</p><p>Select a marker or listing to see what an institution does and how the public can engage with it.</p><div class="card"><strong>Public access and research are different</strong><p>Museums and gardens generally welcome visitors, sometimes with admission. Research campuses and labs are listed for discovery, but require permission for visits.</p></div><div class="section-name">About this pilot</div><p>This statewide discovery collection is growing from Dallas–Fort Worth. It does not claim complete coverage or verified visiting conditions. Filter by region to browse more easily.</p>`;return}
 const bg={'museum':'#EDF5FB','nature_center':'#EFF7EF','botanical_garden':'#EFF7EF','observatory':'#FBF4E4','university':'#FAEFED','research_center':'#FAEFED','zoo_aquarium':'#EFF7EF'}[p.category];
 const fg=ACCESS_COLOR[p.access.level];
 const checked=p.review.status==='verified';const advisory=p.access.advisory==='temporarily_closed'?`<div class="review" style="margin-top:11px;background:#FCEDEA;color:#94372A;border-color:#EEC9C0"><strong>Temporarily closed</strong> · Information checked ${esc(p.access.advisory_as_of||'date unknown')}. Follow the official site for reopening updates.</div>`:'';
 pane.innerHTML=`<div class="sec-label">Location profile</div><span class="pill" style="background:${bg};color:${fg}">${esc(placeLabel(p))}</span><h2>${esc(p.name)}</h2><p>${esc(p.address)}</p>${advisory}<div class="section-name">What you'll find</div><p>${esc(p.summary)}</p>${p.college?'<div class="section-name">STEM programs</div><p>'+p.college.programs.map(esc).join(' · ')+'</p>':'<div class="section-name">Science topics</div>'}${p.college?'':'<div class="tagset">'+p.topics.map(t=>'<span class="topic">'+esc(t)+'</span>').join('')+'</div>'}<div class="section-name">Visitor access</div><div class="access"><strong>${esc(p.access.label)}</strong><p>${esc(p.access.notes)}</p></div><div class="section-name">Editorial check</div><div class="review">${checked?'✓ Reviewed listing':'Source review pending — preliminary profile'}</div><p class="note">Pins show approximate locations, not verified entrances. Confirm public access, admission and directions on the official website.</p><div class="section-name">Institution references</div><a class="link" href="${esc(p.links.official_url)}" target="_blank" rel="noopener noreferrer">Official website ↗</a>${p.review.sources.map(s=>`<a class="link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.purpose)} ↗</a>`).join('')}`;


 // Street geometry is real, but preliminary institution pins are approximate.
 // Search by name and address rather than treating the pin as a verified entrance.
 const streetActions=document.createElement('div');
 streetActions.className='card';
 const maps=document.createElement('a');
 maps.className='link';maps.target='_blank';maps.rel='noopener noreferrer';
 maps.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.name+', '+p.address);
 maps.textContent='Find address and directions in Maps ↗';
 streetActions.appendChild(maps);
 const caution=document.createElement('p');
 caution.className='note';
 caution.textContent='The Atlas pin is approximate. Use the organizer’s official directions to find the correct visitor entrance.';
 streetActions.appendChild(caution);
 pane.appendChild(streetActions);

 // Show dated opportunities on the institution profile without changing access policy.
 const upcoming=EVENTS.filter(e=>e.institution_id===p.id&&new Date(e.start_at).getTime()>=Date.now()).sort((a,b)=>a.start_at.localeCompare(b.start_at)).slice(0,3);
 if(upcoming.length){
  const section=document.createElement('div');section.className='card';
  section.innerHTML=`<strong>Upcoming science events (${upcoming.length})</strong><p>${upcoming.map(e=>esc(e.start_at.slice(0,10)+' · '+e.title)).join('<br>')}</p><button id="seeVenueEvents" type="button" style="margin-top:12px;padding:9px 10px;border-radius:7px;background:#084B9E;color:white;border:0;font-size:12px;font-weight:750">View in events calendar</button><p class="note">Source-checked, pending editorial approval. Restrictions apply.</p>`;
  pane.appendChild(section);
  section.querySelector('#seeVenueEvents').onclick=()=>{initCalendar();const first=upcoming[0];calYear=+first.start_at.slice(0,4);calMonth=+first.start_at.slice(5,7)-1;calSelected=null;$('eventRegion').value='all';$('eventType').value='all';$('eventAccess').value='all';$('eventSearch').value=p.name;showTab('calendar');};
 }
}
