// Calendar view uses a separate event dataset keyed to existing institution IDs.
let calYear,calMonth,monthFormat,dateFormat,clockFormat,calSelected=null;
function initCalendar(){
 if(monthFormat)return;
 const localNowParts=new Intl.DateTimeFormat('en-US',{year:'numeric',month:'numeric',timeZone:'America/Chicago'}).formatToParts(new Date());
 calYear=+localNowParts.find(p=>p.type==='year').value,calMonth=+localNowParts.find(p=>p.type==='month').value-1;
 monthFormat=new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric',timeZone:'America/Chicago'});
 dateFormat=new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:'America/Chicago'});
 clockFormat=new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Chicago'});
}
const eventDay=e=>e.start_at.slice(0,10);
const regionForEvent=e=>PLACES.find(p=>p.id===e.institution_id)?.region||'unknown';
const institutionFor=e=>PLACES.find(p=>p.id===e.institution_id);
const eventLabel={nature:'Nature & ecology',environment:'Conservation',workshop:'Workshop',science_social:'Science social',creative_science:'Creative & science',family:'Family activity',astronomy:'Astronomy',lecture:'Lecture',camp:'Camp',other:'Event'};
function showTab(tab){const isMap=tab==='map';$('atlasMapView').classList.toggle('hidden',!isMap);$('calendarView').classList.toggle('hidden',isMap);$('mapTab').classList.toggle('active',isMap);$('calendarTab').classList.toggle('active',!isMap);$('mapTab').setAttribute('aria-pressed',String(isMap));$('calendarTab').setAttribute('aria-pressed',String(!isMap));if(isMap)map.invalidateSize();else{initCalendar();renderCalendar()}}
function filteredEvents(){
 const region=$('eventRegion').value,kind=$('eventType').value,access=$('eventAccess').value,q=$('eventSearch').value.trim().toLowerCase();
 return EVENTS.filter(e=>{
  const org=institutionFor(e);
  const accessMatch=access==='all'||(access==='public'&&e.access!=='restricted')||(access==='restricted'&&e.access==='restricted');
  return org&&(region==='all'||org.region===region)&&(kind==='all'||e.category===kind)&&accessMatch&&(!q||[e.title,e.summary,e.audience,org.name,org.city].join(' ').toLowerCase().includes(q));
 }).sort((a,b)=>a.start_at.localeCompare(b.start_at));
}
function changeMonth(d){calMonth+=d;if(calMonth<0){calMonth=11;calYear--;}if(calMonth>11){calMonth=0;calYear++;}calSelected=null;renderCalendar();}
function dateKey(year,month,day){return `${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;}
function renderCalendar(){const list=filteredEvents();const monthStart=dateKey(calYear,calMonth,1).slice(0,7);$('calendarHeading').textContent=monthFormat.format(new Date(Date.UTC(calYear,calMonth,10,12)));
 const days=new Date(Date.UTC(calYear,calMonth+1,0)).getUTCDate(),start=new Date(Date.UTC(calYear,calMonth,1)).getUTCDay();const grid=$('calendarGrid');grid.replaceChildren();
 for(let i=0;i<start;i++){const blank=document.createElement('div');blank.className='cal-day empty';blank.setAttribute('aria-hidden','true');grid.appendChild(blank)}
 for(let day=1;day<=days;day++){const d=dateKey(calYear,calMonth,day),hits=list.filter(e=>eventDay(e)===d),btn=document.createElement('button');btn.type='button';btn.className='cal-day'+(calSelected===d?' active':'');btn.setAttribute('aria-label',`${d}, ${hits.length} event${hits.length===1?'':'s'}`);btn.setAttribute('aria-pressed',String(calSelected===d));const t=document.createElement('time');t.dateTime=d;t.textContent=day;btn.append(t);if(hits.length){const b=document.createElement('span');b.className='count'+(hits.every(e=>e.access==='restricted')?' restricted':'');b.textContent=hits.length===1?'1 event':`${hits.length} events`;btn.append(b)}btn.onclick=()=>{calSelected=calSelected===d?null:d;renderCalendar()};grid.append(btn)}
 const shown=list.filter(e=>eventDay(e).startsWith(monthStart)&&(!calSelected||eventDay(e)===calSelected));$('eventListTitle').textContent=calSelected?dateFormat.format(new Date(calSelected+'T12:00:00-06:00')):'Events this month';$('eventCount').textContent=`${shown.length} event${shown.length===1?'':'s'} · ${calSelected?'Selected date':'Current filters'}`;
 const root=$('eventCards');root.replaceChildren();if(!shown.length){root.innerHTML='<div class="no-events">No events match this month and the selected filters. Try another month or include restricted-access programs. Calendar coverage is expanding; entries require rechecking before attending. Not yet a live aggregation feed.</div>';return}
 shown.forEach(e=>{const org=institutionFor(e),card=document.createElement('article');card.className='event-card';const startTime=new Date(e.start_at),endTime=e.end_at?new Date(e.end_at):null,sameDay=!endTime||e.start_at.slice(0,10)===e.end_at.slice(0,10);const when=`${dateFormat.format(startTime)} · ${clockFormat.format(startTime)}`+(endTime?(sameDay?`–${clockFormat.format(endTime)}`:`–${dateFormat.format(endTime)} ${clockFormat.format(endTime)}`):' · end time not listed');const status=e.access==='restricted'?'Restricted / institution-affiliated':e.access==='registration'?'Registration may be required':'Public program';card.innerHTML=`<h4>${esc(e.title)}</h4><div class="meta">${esc(when)} · CT</div><div class="meta">${esc(e.delivery==='online'?'Online session · '+org.name:org.name+' · '+org.city)}</div><div class="event-tags"><span class="event-tag">${esc(eventLabel[e.category])}</span><span class="event-tag ${e.access==='restricted'?'restricted':''}">${esc(status)}</span></div><p class="event-desc">${esc(e.summary)}</p>${e.availability_note?`<p class="event-desc"><strong>Tickets:</strong> ${esc(e.availability_note)}</p>`:""}<div class="meta">For: ${esc(e.audience)} · Official source checked ${esc(e.source_checked_at)}</div><div class="event-links"><a href="${esc(e.source_url)}" target="_blank" rel="noopener noreferrer">Official event information ↗</a><button type="button">Add to calendar (.ics)</button></div>`;card.querySelector('button').onclick=()=>saveIcs(e);root.appendChild(card)})
}
function icsEscape(s){return String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function saveIcs(e){const start=new Date(e.start_at).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');const end=e.end_at?new Date(e.end_at).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z'):null;const org=institutionFor(e);const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Frameworked//Science Atlas//EN','BEGIN:VEVENT',`UID:${e.id}@frameworked.org`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}`,`DTSTART:${start}`,...(end?[`DTEND:${end}`]:[]),`SUMMARY:${icsEscape(e.title)}`,`LOCATION:${icsEscape(e.delivery==='online'?'Online — see organizer link':org.name+', '+org.city+', Texas')}`,`DESCRIPTION:${icsEscape(e.summary+' — Verify schedule and access on the organizer site: '+e.source_url)}`,`URL:${e.source_url}`,'END:VEVENT','END:VCALENDAR'];const blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=e.id+'.ics';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('mapTab').onclick=()=>showTab('map');$('calendarTab').onclick=()=>showTab('calendar');$('prevMonth').onclick=()=>changeMonth(-1);$('nextMonth').onclick=()=>changeMonth(1);$('todayMonth').onclick=()=>{const now=new Date(),parts=new Intl.DateTimeFormat('en-US',{year:'numeric',month:'numeric',timeZone:'America/Chicago'}).formatToParts(now);calYear=+parts.find(p=>p.type==='year').value;calMonth=+parts.find(p=>p.type==='month').value-1;calSelected=null;renderCalendar()};
['eventRegion','eventType','eventAccess'].forEach(id=>$(id).onchange=()=>{calSelected=null;renderCalendar()});$('eventSearch').oninput=()=>{calSelected=null;renderCalendar()};

